    if env.is_xeno then return "Xeno" end
    if env.syn then return "Synapse" end
    local ok3, re = pcall(function() return getrenv and getrenv() end)
    if ok3 and type(re) == "table" and _rawget(re, "solara") then return "Solara" end
    return "Unknown"
