    if not fakeReq then
        local hs = game:GetService("HttpService")
        local function J(t)
            local ok,r = pcall(function() return hs:JSONEncode(t) end)
            return ok and r or "{}"
        end
        fakeReq = function(opts)
            local url = type(opts)=="table" and tostring(opts.Url or opts.url or "") or tostring(opts or "")
